workflow = input().strip().split(',')
if 'Clean Data' in workflow and 'Train Model' in workflow:
    idx_clean = workflow.index('Clean Data')
    idx_train = workflow.index('Train Model')
    if idx_clean < idx_train:
        print('Valid Workflow')
    else:
        print('Invalid Workflow')
else:
    print('Invalid Workflow')

number = int(input())
if number > 0:
    print('Positive')
elif number < 0:
    print('Negative')
else:
    print('Zero')

age = int(input())
if age < 13:
    print('Child')
elif age <= 19:
    print('Teen')
else:
    print('Adult')
